import java.util.*;

class Solution {
    public int pathSum(TreeNode root, int targetSum) {
        Map<Long, Integer> prefixMap = new HashMap<>();
        prefixMap.put(0L, 1);
        return dfs(root, 0L, targetSum, prefixMap);
    }

    private int dfs(TreeNode node, long currentSum, int target, Map<Long, Integer> prefixMap) {
        if (node == null) return 0;

        currentSum += node.val;
        int count = prefixMap.getOrDefault(currentSum - target, 0);

        prefixMap.merge(currentSum, 1, Integer::sum);

        count += dfs(node.left, currentSum, target, prefixMap);
        count += dfs(node.right, currentSum, target, prefixMap);

        prefixMap.merge(currentSum, -1, Integer::sum);
        if (prefixMap.get(currentSum) == 0) {
            prefixMap.remove(currentSum);
        }

        return count;
    }
}

class Solution {
    public int pathSum(TreeNode root, int targetSum) {
        if (root == null) return 0;

        return countFrom(root, targetSum)
            + pathSum(root.left, targetSum)
            + pathSum(root.right, targetSum);
    }

    private int countFrom(TreeNode node, long remain) {
        if (node == null) return 0;

        int count = (node.val == remain) ? 1 : 0;
        count += countFrom(node.left, remain - node.val);
        count += countFrom(node.right, remain - node.val);

        return count;
    }
}

import java.util.*;

class Solution {
    private int count = 0;

    public int pathSum(TreeNode root, int targetSum) {
        dfs(root, targetSum, new ArrayList<>());
        return count;
    }

    private void dfs(TreeNode node, int targetSum, List<Integer> path) {
        if (node == null) {
            return;
        }

        path.add(node.val);
        long suffixSum = 0;
        for (int i = path.size() - 1; i >= 0; i--) {
            suffixSum += path.get(i);
            if (suffixSum == targetSum) {
                count++;
            }
        }

        dfs(node.left, targetSum, path);
        dfs(node.right, targetSum, path);
        path.remove(path.size() - 1);
    }
}

import java.util.*;

class Solution {
    private static final class Frame {
        final TreeNode node;
        final long prefix;
        final boolean exit;

        Frame(TreeNode node, long prefix, boolean exit) {
            this.node = node;
            this.prefix = prefix;
            this.exit = exit;
        }
    }

    public int pathSum(TreeNode root, int targetSum) {
        if (root == null) {
            return 0;
        }

        Map<Long, Integer> prefixCounts = new HashMap<>();
        prefixCounts.put(0L, 1);
        Deque<Frame> stack = new ArrayDeque<>();
        stack.push(new Frame(root, 0L, false));
        int total = 0;

        while (!stack.isEmpty()) {
            Frame frame = stack.pop();
            TreeNode node = frame.node;
            if (frame.exit) {
                prefixCounts.merge(frame.prefix, -1, Integer::sum);
                if (prefixCounts.get(frame.prefix) == 0) {
                    prefixCounts.remove(frame.prefix);
                }
                continue;
            }

            long current = frame.prefix + node.val;
            total += prefixCounts.getOrDefault(current - targetSum, 0);
            prefixCounts.merge(current, 1, Integer::sum);

            stack.push(new Frame(node, current, true));
            if (node.right != null) {
                stack.push(new Frame(node.right, current, false));
            }
            if (node.left != null) {
                stack.push(new Frame(node.left, current, false));
            }
        }

        return total;
    }
}
